import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";import"./chunks/assets.NJs4UO-Q.js";var i=JSON.parse(`{"title":"错误参考（Error Reference）","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code/error-reference.md","filePath":"zh/kimi-code/error-reference.md"}`),a={name:`kimi-code/error-reference.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="错误参考-error-reference" tabindex="-1">错误参考（Error Reference） <a class="header-anchor" href="#错误参考-error-reference" aria-label="Permalink to “错误参考（Error Reference）”">​</a></h1><p>本文档收录的是调用 Kimi Code API 时可能遇到的<strong>服务端错误</strong>和<strong>工具调用错误</strong>，包括权限、限流、请求格式、服务器内部等问题。如果你遇到的是客户端本身的问题（如 CLI 安装失败、IDE 连接异常、MCP 配置错误等），请参考 <a href="#">常见问题 FAQ</a>。</p><p>根据终端或客户端显示的报错信息，在下表中找到对应条目，查看含义和处理方式。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果你使用的是 OpenCode、Claude Code 等第三方客户端，客户端自身可能对错误码进行了转换或重新包装，导致你看到的错误码与本文档不一致。这种情况下，请<strong>以报错信息中的文字内容为主</strong>，在下方快速查找表中匹配关键词，找到对应条目。</p></div><h2 id="快速查找" tabindex="-1">快速查找 <a class="header-anchor" href="#快速查找" aria-label="Permalink to “快速查找”">​</a></h2><p>报错分两类：<strong>模型调用错误</strong>发生在请求模型生成回复的过程中（认证、限流、请求格式等）；<strong>工具调用错误</strong>发生在 AI 执行工具调用的过程中（如读取网页、处理图片）。按报错来源在下方对应表格中匹配关键词。</p><h3 id="模型调用" tabindex="-1">模型调用 <a class="header-anchor" href="#模型调用" aria-label="Permalink to “模型调用”">​</a></h3><table tabindex="0"><thead><tr><th>看到的报错关键词</th><th>HTTP 状态码</th><th>跳转章节</th></tr></thead><tbody><tr><td><code>The API Key appears to be invalid or may have expired</code></td><td>401</td><td><a href="#api-key-无效">认证错误</a></td></tr><tr><td><code>Invalid Authentication</code></td><td>401</td><td><a href="#invalid-authentication">认证错误</a></td></tr><tr><td><code>Your current subscription does not have access to k3</code></td><td>401</td><td><a href="#无-k3-访问权限">权限错误</a></td></tr><tr><td><code>Your current plan supports only kimi-k3 up to 256K context</code></td><td>401</td><td><a href="#无-1m-访问权限">权限错误</a></td></tr><tr><td><code>Your current subscription does not have access to kimi-for-coding-highspeed</code></td><td>401</td><td><a href="#高速版无访问权限">权限错误</a></td></tr><tr><td><code>Your model id does not exist, recognized as other:</code></td><td>401</td><td><a href="#模型-id-不存在">权限错误</a></td></tr><tr><td><code>unable to verify your membership benefits</code></td><td>402</td><td><a href="#会员权益无法验证">会员权益异常</a></td></tr><tr><td><code>You&#39;ve reached your usage limit for this billing cycle</code></td><td>403</td><td><a href="#计费周期配额耗尽">权限错误</a></td></tr><tr><td><code>Access terminated</code></td><td>403</td><td><a href="#账号访问终止">权限错误</a></td></tr><tr><td><code>The engine is currently overloaded</code></td><td>429</td><td><a href="#推理引擎过载">限流与配额</a></td></tr><tr><td><code>We&#39;re receiving too many requests</code></td><td>429</td><td><a href="#并发请求过多">限流与配额</a></td></tr><tr><td><code>You&#39;ve reached your usage limit for this period</code></td><td>429</td><td><a href="#_5-小时限额触顶">限流与配额</a></td></tr><tr><td><code>You&#39;ve reached kimi monthly usage limit</code></td><td>429</td><td><a href="#会员月度额度耗尽">限流与配额</a></td></tr><tr><td><code>total message size N exceeds limit 2097152</code></td><td>400</td><td><a href="#消息体超出上下文限制">请求格式错误</a></td></tr><tr><td><code>Your request exceeded model token limit: 262144</code></td><td>400</td><td><a href="#token-超限">请求格式错误</a></td></tr><tr><td><code>thinking is enabled but reasoning_content is missing</code></td><td>400</td><td><a href="#思维链字段缺失">请求格式错误</a></td></tr><tr><td><code>unsupported image url</code></td><td>400</td><td><a href="#不支持的图片-url">请求格式错误</a></td></tr><tr><td><code>function name ... is duplicated</code></td><td>400</td><td><a href="#工具名重复">请求格式错误</a></td></tr><tr><td><code>The request was rejected because it was considered high risk</code></td><td>400</td><td><a href="#内容安全拦截">请求格式错误</a></td></tr><tr><td><code>Not found the model kimi-for-coding or Permission denied</code></td><td>404</td><td><a href="#模型未找到">资源未找到</a></td></tr><tr><td><code>method not found</code></td><td>404</td><td><a href="#接口路径不存在">资源未找到</a></td></tr><tr><td><code>bot_id ... value does not match id_kinds</code></td><td>500</td><td><a href="#bot-id-格式不合规">服务端内部错误</a></td></tr><tr><td><code>failed to connect to ... database=membership_</code></td><td>500</td><td><a href="#数据库连接失败">服务端内部错误</a></td></tr><tr><td><code>FATAL: terminating connection due to administrator command</code></td><td>500</td><td><a href="#数据库连接失败">服务端内部错误</a></td></tr><tr><td><code>failed to evaluate rate limit script</code></td><td>500</td><td><a href="#内部连接异常">服务端内部错误</a></td></tr><tr><td><code>i/o timeout</code> / <code>conn closed</code> / <code>bad connection</code></td><td>500</td><td><a href="#内部连接异常">服务端内部错误</a></td></tr><tr><td><code>503 Service Unavailable</code> / <code>504 Gateway Timeout</code> / <code>502 Bad Gateway</code></td><td>500</td><td><a href="#下游服务不可用">服务端内部错误</a></td></tr><tr><td><code>未找到该账号</code> / <code>该账号已被禁用</code> / <code>已被禁言</code></td><td>500</td><td><a href="#账号状态异常">服务端内部错误</a></td></tr></tbody></table><h3 id="工具调用" tabindex="-1">工具调用 <a class="header-anchor" href="#工具调用" aria-label="Permalink to “工具调用”">​</a></h3><table tabindex="0"><thead><tr><th>看到的报错关键词</th><th>HTTP 状态码</th><th>跳转章节</th></tr></thead><tbody><tr><td><code>context canceled</code></td><td>499</td><td><a href="#请求被取消">工具调用错误</a></td></tr><tr><td><code>url2text</code> / <code>spider checkUrl failed</code> / <code>invalid html</code></td><td>500</td><td><a href="#网页读取失败">工具调用错误</a></td></tr><tr><td><code>image_url:moderation request error</code></td><td>500</td><td><a href="#图片审核失败">工具调用错误</a></td></tr><tr><td><code>We consider the current URL poses a security risk</code></td><td>403</td><td><a href="#url-安全风险拦截">工具调用错误</a></td></tr><tr><td><code>invalid_url: The provided URL is invalid</code></td><td>400</td><td><a href="#url-格式无效">工具调用错误</a></td></tr></tbody></table><h2 id="认证错误" tabindex="-1">认证错误 <a class="header-anchor" href="#认证错误" aria-label="Permalink to “认证错误”">​</a></h2><p><strong>HTTP 401</strong></p><p>请求未携带有效凭证，或凭证已失效。服务端在处理请求之前会先验证身份，401 表示这一步没有通过。<strong>不需要重试</strong>，修复凭证后重新发送请求。</p><h3 id="api-key-无效" tabindex="-1">API Key 无效 <a class="header-anchor" href="#api-key-无效" aria-label="Permalink to “API Key 无效”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 401, message: The API Key appears to be invalid or may have expired. Please verify your credentials and try again.</span></span></code></pre></div><p>API Key 填写有误，或该 Key 已在控制台被撤销/过期。</p><p><strong>处理方式：</strong></p><ul><li><strong>密钥输入错误</strong>：检查是否有多余的空格或遗漏的字符</li><li><strong>密钥已过期或被撤销</strong>：前往<a href="https://www.kimi.com/code/console?from=kfc_overview_topbar" target="_blank" rel="noreferrer">控制台</a> › API Keys 确认密钥状态</li><li><strong>环境变量覆盖</strong>：检查是否有 <code>KIMI_API_KEY</code> 或 <code>OPENAI_API_KEY</code> 环境变量覆盖了配置文件中的密钥，可运行 <code>echo $KIMI_API_KEY</code> 检查；如果发现环境变量中配置了旧 Key，请更新为正确的 Key，或删除错误的环境变量后重新启动服务</li></ul><h3 id="invalid-authentication" tabindex="-1">Invalid Authentication <a class="header-anchor" href="#invalid-authentication" aria-label="Permalink to “Invalid Authentication”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 401, message: Invalid Authentication</span></span></code></pre></div><p>请求未携带有效凭证，或使用了不支持的认证格式。</p><p><strong>处理方式：</strong></p><p>最常见原因是误用了开放平台的 Key 或 URL。Kimi Code 和 <a href="https://platform.kimi.com" target="_blank" rel="noreferrer">Kimi 开放平台</a> 是两套独立系统，Key 和 Base URL 均不通用：</p><ul><li>Kimi Code：Key 从<a href="https://www.kimi.com/code/console?from=kfc_overview_topbar" target="_blank" rel="noreferrer">控制台</a>获取，Base URL 为 <code>https://api.kimi.com/coding/v1</code>（OpenAI 协议）或 <code>https://api.kimi.com/coding/</code>（Anthropic 协议）</li><li>开放平台：Key 从 <a href="https://platform.kimi.com" target="_blank" rel="noreferrer">platform.kimi.com</a> 获取，Base URL 为 <code>https://api.moonshot.cn/v1</code></li></ul><h2 id="会员权益异常" tabindex="-1">会员权益异常 <a class="header-anchor" href="#会员权益异常" aria-label="Permalink to “会员权益异常”">​</a></h2><p><strong>HTTP 402</strong></p><p>服务端无法确认当前账号的订阅状态，通常为临时性问题。</p><h3 id="会员权益无法验证" tabindex="-1">会员权益无法验证 <a class="header-anchor" href="#会员权益无法验证" aria-label="Permalink to “会员权益无法验证”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 402, message: We&#39;re unable to verify your membership benefits at this time. Please ensure your membership is active.</span></span></code></pre></div><p><strong>处理方式：</strong></p><ul><li>确认 Kimi Code 订阅仍在有效期内</li><li>等待片刻后重试</li><li>如持续出现，前往<a href="https://www.kimi.com/code/console?from=kfc_overview_topbar" target="_blank" rel="noreferrer">控制台</a>检查订阅状态或联系 <a href="mailto:code@moonshot.ai" target="_blank" rel="noreferrer">code@moonshot.ai</a></li></ul><h2 id="权限错误" tabindex="-1">权限错误 <a class="header-anchor" href="#权限错误" aria-label="Permalink to “权限错误”">​</a></h2><p><strong>HTTP 401 / 403</strong></p><p>请求本身格式正确，身份也已验证，但当前账号没有权限执行该操作——可能是订阅档位不包含该能力（如高速版），或是访问被控制（账号终止），或是配额耗尽（超出被允许的使用量）。<strong>重试无意义</strong>，需要解决权限或配额问题本身。</p><h3 id="无-k3-访问权限" tabindex="-1">无 K3 访问权限 <a class="header-anchor" href="#无-k3-访问权限" aria-label="Permalink to “无 K3 访问权限”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 401, message: Your current subscription does not have access to k3. Upgrade to an Moderato plan or above. Upgrade: https://www.kimi.com/membership/pricing?from=server_k3_error</span></span></code></pre></div><p>当前订阅未包含 <code>k3</code> 的访问权限。K3 需要 Moderato 及以上套餐才能调用。</p><p><strong>处理方式：</strong></p><ul><li><a href="https://www.kimi.com/code/#pricing" target="_blank" rel="noreferrer">升级订阅</a>到 Moderato 及以上套餐即可调用 <code>k3</code></li><li>暂不升级时，可继续使用标准版 <code>kimi-for-coding</code></li></ul><h3 id="无-1m-访问权限" tabindex="-1">无 1M 访问权限 <a class="header-anchor" href="#无-1m-访问权限" aria-label="Permalink to “无 1M 访问权限”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 401, message: Your current plan supports only kimi-k3 up to 256K context. 1M context is available on higher-tier plans. Upgrade: https://www.kimi.com/membership/pricing?from=server_k3_error</span></span></code></pre></div><p>当前套餐调用 <code>k3</code> 时仅支持最高 256K 上下文；如需使用最高 1M 上下文，需升级至 Allegretto 及以上套餐。</p><p><strong>处理方式：</strong></p><ul><li><a href="https://www.kimi.com/code/#pricing" target="_blank" rel="noreferrer">升级订阅</a>到 Allegretto 及以上套餐即可使用 <code>k3</code> 的最高 1M 上下文</li><li>暂不升级时，可继续使用 <code>k3</code> 的 256K 上下文，或切换到标准版 <code>kimi-for-coding</code></li></ul><h3 id="模型-id-不存在" tabindex="-1">模型 ID 不存在 <a class="header-anchor" href="#模型-id-不存在" aria-label="Permalink to “模型 ID 不存在”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 401, message: Your model id does not exist, recognized as other:&lt;model-id&gt;. Please set model id as \`&lt;correct-model-id&gt;\`.</span></span></code></pre></div><p>请求中使用的模型 ID 不被模型侧识别。常见原因是把只在特定场景使用的写法填到了不支持该写法的入口。例如 <code>k3[1m]</code>（带外层引号）仅在 Claude Code 环境变量场景中用于显式声明 1M 上下文窗口；在 API 请求、其他第三方工具的 Model ID 字段等场景中，应直接使用 <code>k3</code>。</p><p><strong>处理方式：</strong></p><ul><li>检查报错中 <code>recognized as other:</code> 后面的实际 model id，确认没有拼写错误或多加符号</li><li>如果是 Claude Code 环境变量配置，确认已按 <a href="/code/docs/third-party-tools/claude-code.html">在更多第三方工具中使用</a> 的示例填写，包括外层引号</li><li>如果是 API 请求或其他第三方工具，将 Model ID 改为标准形式（如 <code>k3</code>、<code>kimi-for-coding</code>、<code>kimi-for-coding-highspeed</code>），避免使用仅适用于 Claude Code env 的 <code>k3[1m]</code> 写法</li></ul><h3 id="高速版无访问权限" tabindex="-1">高速版无访问权限 <a class="header-anchor" href="#高速版无访问权限" aria-label="Permalink to “高速版无访问权限”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 401, message: Your current subscription does not have access to kimi-for-coding-highspeed. Upgrade to an Allegretto plan or above. Upgrade: https://www.kimi.com/membership/pricing?from=server_highspeed_error</span></span></code></pre></div><p>当前账号的订阅未包含高速版模型 <code>kimi-for-coding-highspeed</code> 的访问权限。高速版与标准版 <code>kimi-for-coding</code> 是同一个模型，但输出速度约为标准版的 5–6 倍，需要 Allegretto 及以上套餐才能使用。</p><p><strong>处理方式：</strong></p><ul><li><a href="https://www.kimi.com/membership/pricing?from=server_highspeed_error" target="_blank" rel="noreferrer">升级订阅</a>到 Allegretto 及以上套餐即可解锁高速版</li><li>暂不升级时，可继续使用标准版 <code>kimi-for-coding</code>，功能与高速版完全一致，仅输出速度较慢</li></ul><h3 id="计费周期配额耗尽" tabindex="-1">计费周期配额耗尽 <a class="header-anchor" href="#计费周期配额耗尽" aria-label="Permalink to “计费周期配额耗尽”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 403, message: You&#39;ve reached your usage limit for this billing cycle. Your quota will be refreshed in the next cycle.</span></span></code></pre></div><p>账户当前周额度已全部用完。</p><p><strong>处理方式：</strong></p><ul><li>等待下个计费周期刷新</li><li>前往<a href="https://www.kimi.com/code/console?from=kfc_overview_topbar" target="_blank" rel="noreferrer">控制台</a>查看额度使用情况</li><li><a href="https://www.kimi.com/membership/pricing?from=upgrade_plan&amp;track_id=5b8a0861-96ab-424d-b015-5992ec9ab98a" target="_blank" rel="noreferrer">升级订阅</a>获取更高配额</li></ul><h3 id="账号访问终止" tabindex="-1">账号访问终止 <a class="header-anchor" href="#账号访问终止" aria-label="Permalink to “账号访问终止”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 403, message: Access terminated.</span></span></code></pre></div><p>账号因违反社区规范被终止访问。</p><p><strong>处理方式：</strong></p><ul><li>前往 <a href="./community-guidelines.html">Kimi Code 社区倡议</a> 了解违规原因及判定范围</li><li>如需申诉，请发送邮件至 <a href="mailto:support@moonshot.cn" target="_blank" rel="noreferrer">support@moonshot.cn</a>，并在邮件中说明风控的大致情况</li></ul><h2 id="限流与配额" tabindex="-1">限流与配额 <a class="header-anchor" href="#限流与配额" aria-label="Permalink to “限流与配额”">​</a></h2><p><strong>HTTP 429</strong></p><p>请求频次或使用量超出了限制。分两种性质：推理引擎过载属于服务端容量问题，<strong>直接重试即可</strong>；配额类错误属于账户使用量问题，<strong>重试无意义</strong>，需等待重置或升级套餐。</p><h3 id="推理引擎过载" tabindex="-1">推理引擎过载 <a class="header-anchor" href="#推理引擎过载" aria-label="Permalink to “推理引擎过载”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 429, message: The engine is currently overloaded, please try again later</span></span></code></pre></div><p>服务端当前请求量超出推理容量，<strong>与个人配额和账户状态无关</strong>。 工作日高峰期（14:00-17:00）可能会触发，Kimi Code会及时处理，为你提供更丝滑的体验，也可避开高峰期请求</p><p><strong>处理方式：</strong></p><ul><li>稍等片刻后重试</li></ul><h3 id="并发请求过多" tabindex="-1">并发请求过多 <a class="header-anchor" href="#并发请求过多" aria-label="Permalink to “并发请求过多”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 429, message: We&#39;re receiving too many requests at the moment. Please wait a moment and try again.</span></span></code></pre></div><p>短时间内发出的请求太多，超出了账户限制。</p><p><strong>处理方式：</strong></p><ul><li>稍等片刻后重试，避免连续快速地重复发送请求</li></ul><h3 id="_5-小时限额触顶" tabindex="-1">5 小时限额触顶 <a class="header-anchor" href="#_5-小时限额触顶" aria-label="Permalink to “5 小时限额触顶”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 429, message: You&#39;ve reached your usage limit for this period. Your quota will be refreshed in the next period.</span></span></code></pre></div><p>当前 5 小时滚动窗口内的调用量已达上限。</p><p><strong>处理方式：</strong></p><ul><li>等待限额窗口重置，可前往<a href="https://www.kimi.com/code/console?from=kfc_overview_topbar" target="_blank" rel="noreferrer">控制台</a>查看重置时间</li><li><a href="https://www.kimi.com/membership/pricing?from=upgrade_plan&amp;track_id=5b8a0861-96ab-424d-b015-5992ec9ab98a" target="_blank" rel="noreferrer">升级订阅</a>提升限额上限</li></ul><h3 id="会员月度额度耗尽" tabindex="-1">会员月度额度耗尽 <a class="header-anchor" href="#会员月度额度耗尽" aria-label="Permalink to “会员月度额度耗尽”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 429, message: You&#39;ve reached kimi monthly usage limit for this billing cycle. Your quota will be refreshed in the next cycle.</span></span></code></pre></div><p>你的 Kimi <a href="https://www.kimi.com/membership/subscription" target="_blank" rel="noreferrer">月度额度</a>已全部用完。</p><p>Kimi 的所有会员权益——包括 PPT、Agent 集群、Kimi Code 等共用同一套月度额度。一旦总额度耗尽，即使 Kimi Code 还有剩余额度，也继续发起请求，需等待下个月额度自动刷新或升级会员计划，详情见<a href="https://www.kimi.com/membership-credits" target="_blank" rel="noreferrer">Kimi 会员额度计费说明</a>。额度耗尽后账户进入冻结状态，如下图所示：</p><p><img src="/code/docs/%E6%9C%88%E9%99%90%E9%A2%9D.png" alt="月度额度耗尽冻结状态"></p><p><strong>处理方式：</strong></p><ul><li>等待下个计费周期自动重置</li><li><a href="https://www.kimi.com/membership/pricing?from=upgrade_plan&amp;track_id=5b8a0861-96ab-424d-b015-5992ec9ab98a" target="_blank" rel="noreferrer">升级订阅</a>获取更高的月度额度</li></ul><h2 id="请求格式错误" tabindex="-1">请求格式错误 <a class="header-anchor" href="#请求格式错误" aria-label="Permalink to “请求格式错误”">​</a></h2><p><strong>HTTP 400</strong></p><p>请求内容本身有问题，服务端在解析或校验阶段就拒绝了。<strong>修改请求内容即可解决，无需等待或联系支持。</strong></p><h3 id="消息体超出上下文限制" tabindex="-1">消息体超出上下文限制 <a class="header-anchor" href="#消息体超出上下文限制" aria-label="Permalink to “消息体超出上下文限制”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 400, message: total message size 5943865 exceeds limit 2097152</span></span></code></pre></div><p>所有消息（含历史对话、系统提示、工具结果）加起来超过 2MB 上下文限制。这是出现频率最高的 400 错误。</p><p><strong>处理方式：</strong></p><ul><li>精简对话历史，删除不必要的早期轮次</li><li>分段处理长文本，控制单次请求体积</li></ul><h3 id="token-超限" tabindex="-1">Token 超限 <a class="header-anchor" href="#token-超限" aria-label="Permalink to “Token 超限”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 400, message: Invalid request: Your request exceeded model token limit: 262144 (requested: 558009)</span></span></code></pre></div><p>请求的 token 数超过模型单次处理上限（262,144 tokens）。</p><p><strong>处理方式：</strong></p><ul><li>缩短 prompt 长度或截断历史对话</li><li>分多次请求处理长文本</li></ul><h3 id="思维链字段缺失" tabindex="-1">思维链字段缺失 <a class="header-anchor" href="#思维链字段缺失" aria-label="Permalink to “思维链字段缺失”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 400, message: thinking is enabled but reasoning_content is missing in assistant tool call message at index 2</span></span></code></pre></div><p>启用了思维链（thinking）模式，但工具调用消息中缺少 <code>reasoning_content</code> 字段。这是 Kimi Code 特有字段，启用思维链时必须携带。</p><p><strong>处理方式：</strong></p><ul><li>在工具调用的 assistant 消息中补充 <code>reasoning_content</code> 字段</li><li>参考 <a href="/code/docs/kimi-code-cli/configuration/providers.html">平台与模型</a> 查看思维链字段规范</li></ul><h3 id="不支持的图片-url" tabindex="-1">不支持的图片 URL <a class="header-anchor" href="#不支持的图片-url" aria-label="Permalink to “不支持的图片 URL”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 400, message: Invalid request: unsupported image url: C:\\Users\\pc\\...\\screenshot.jpg</span></span></code></pre></div><p>传入的图片 URL 格式不支持：本地路径、非标准 base64 前缀，或不支持的外部域名。</p><p><strong>处理方式：</strong></p><ul><li>本地路径需上传至可公开访问的 URL</li><li>base64 图片需使用标准格式：<code>data:image/jpeg;base64,...</code></li></ul><h3 id="工具名重复" tabindex="-1">工具名重复 <a class="header-anchor" href="#工具名重复" aria-label="Permalink to “工具名重复”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 400, message: function name unnamed_function is duplicated</span></span></code></pre></div><p><code>tools</code> 数组中存在同名工具定义。</p><p><strong>处理方式：</strong></p><ul><li>确保每个工具的 <code>name</code> 字段唯一</li></ul><h3 id="内容安全拦截" tabindex="-1">内容安全拦截 <a class="header-anchor" href="#内容安全拦截" aria-label="Permalink to “内容安全拦截”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 400, message: The request was rejected because it was considered high risk</span></span></code></pre></div><p>请求内容触发了内容安全检测，服务端拒绝处理。</p><p><strong>处理方式：</strong></p><ul><li>检查 prompt 中是否包含敏感内容，修改后重试</li><li>如认为是误判，发送邮件至 <a href="mailto:code@moonshot.ai" target="_blank" rel="noreferrer">code@moonshot.ai</a> 并附上触发报错的请求内容</li></ul><h2 id="资源未找到" tabindex="-1">资源未找到 <a class="header-anchor" href="#资源未找到" aria-label="Permalink to “资源未找到”">​</a></h2><p><strong>HTTP 404</strong></p><p>请求的资源不存在，或当前账号无权访问。检查模型名称和接口路径是否正确。</p><h3 id="模型未找到" tabindex="-1">模型未找到 <a class="header-anchor" href="#模型未找到" aria-label="Permalink to “模型未找到”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error, status code: 404, message: Not found the model kimi-for-coding or Permission denied</span></span></code></pre></div><p><strong>处理方式：</strong></p><ul><li>确认模型名称拼写正确（<code>kimi-for-coding</code>）；常见错误拼写：<code>Kimi For Coding</code>、<code>Kimi-for-Coding</code>、<code>kimi-for-code</code>、<code>kimi-code</code>、<code>K2.6</code></li><li>确认账号已开通 <a href="https://kimi.com/code" target="_blank" rel="noreferrer">Kimi Code</a> 访问权限</li></ul><h3 id="接口路径不存在" tabindex="-1">接口路径不存在 <a class="header-anchor" href="#接口路径不存在" aria-label="Permalink to “接口路径不存在”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>method not found</span></span></code></pre></div><p><strong>处理方式：</strong></p><ul><li>检查请求 URL 是否正确，Kimi Code 的 Base URL 为 <code>https://api.kimi.com/coding/v1</code>（OpenAI 协议）或 <code>https://api.kimi.com/coding/</code>（Anthropic 协议）</li></ul><h2 id="服务端内部错误" tabindex="-1">服务端内部错误 <a class="header-anchor" href="#服务端内部错误" aria-label="Permalink to “服务端内部错误”">​</a></h2><p><strong>HTTP 500</strong></p><p>服务端发生了意外错误，<strong>不由请求内容或账户状态引起</strong>。大多数情况下等待片刻后重试即可恢复，如持续出现请通过邮箱<a href="mailto:code@moonshot.ai" target="_blank" rel="noreferrer">code@moonshot.ai</a>提交反馈。</p><h3 id="bot-id-格式不合规" tabindex="-1">bot_id 格式不合规 <a class="header-anchor" href="#bot-id-格式不合规" aria-label="Permalink to “bot_id 格式不合规”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>invalid_argument: field kimi.billing.v1.ClawExtension.bot_id: value &quot;KIMI_CLAW_ID&quot; (id_kind=uuid_v4): value does not match id_kinds: [uuid_v4]</span></span>
<span class="line"><span>invalid_argument: field kimi.billing.v1.ClawExtension.bot_id: value &quot;openclaw-local&quot; (id_kind=uuid_v4): value does not match id_kinds: [uuid_v4]</span></span></code></pre></div><p><code>bot_id</code> 不是合法的 UUID v4 格式。这是客户端软件在发请求时自动附上的字段，通常由客户端负责填写，用户无需手动设置。</p><p><strong>处理方式：</strong></p><ul><li>更新到最新版本的客户端后重试</li><li>如更新后仍出现，发送邮件至 <a href="mailto:code@moonshot.ai" target="_blank" rel="noreferrer">code@moonshot.ai</a> 并附上完整报错信息</li></ul><h3 id="数据库连接失败" tabindex="-1">数据库连接失败 <a class="header-anchor" href="#数据库连接失败" aria-label="Permalink to “数据库连接失败”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>internal: failed to connect to \`user=kimi_chat_prod_rw database=membership_009\`: ...: connection reset by peer</span></span>
<span class="line"><span>internal: FATAL: terminating connection due to administrator command (SQLSTATE 57P03)</span></span></code></pre></div><p>服务端无法连接会员资格校验数据库，或数据库正在维护重启。属于基础设施层故障。</p><p><strong>处理方式：</strong></p><ul><li>等待 1-2 分钟后重试</li></ul><h3 id="内部连接异常" tabindex="-1">内部连接异常 <a class="header-anchor" href="#内部连接异常" aria-label="Permalink to “内部连接异常”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>internal: conn closed</span></span>
<span class="line"><span>internal: driver: bad connection</span></span>
<span class="line"><span>internal: read tcp ...: i/o timeout</span></span>
<span class="line"><span>internal: unexpected EOF</span></span>
<span class="line"><span>internal: failed to evaluate rate limit script: read tcp ...: i/o timeout</span></span></code></pre></div><p>服务端内部网络连接异常，涵盖连接被重置、I/O 超时、Redis 限流脚本超时等多种底层错误，通常为瞬态故障。</p><p><strong>处理方式：</strong></p><ul><li>稍等片刻后重试（初始等待 1 秒，最多重试 3 次）</li></ul><h3 id="下游服务不可用" tabindex="-1">下游服务不可用 <a class="header-anchor" href="#下游服务不可用" aria-label="Permalink to “下游服务不可用”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unavailable: 503 Service Unavailable</span></span>
<span class="line"><span>unavailable: 504 Gateway Timeout</span></span>
<span class="line"><span>unavailable: 502 Bad Gateway</span></span></code></pre></div><p>服务端调用下游模型或基础组件时收到 5xx 响应。</p><p><strong>处理方式：</strong></p><ul><li>等待片刻后重试</li></ul><h3 id="账号状态异常" tabindex="-1">账号状态异常 <a class="header-anchor" href="#账号状态异常" aria-label="Permalink to “账号状态异常”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unauthenticated: not_found: 未找到该账号，请确认是否注册</span></span>
<span class="line"><span>unauthenticated: failed_precondition: 因违反用户协议，该账号已被禁用。</span></span>
<span class="line"><span>unauthenticated: failed_precondition: 因违反用户协议，该账号已被暂时禁用。</span></span>
<span class="line"><span>unauthenticated: failed_precondition: 因违反用户协议，该账号已被禁言。</span></span></code></pre></div><p>服务端查询账号信息时发现账号不存在或处于异常状态。</p><p><strong>处理方式：</strong></p><ul><li>账号未注册：确认使用的账号已完成注册</li><li>账号被禁用/禁言：发送邮件至 <a href="mailto:support@kimi-code.com" target="_blank" rel="noreferrer">support@kimi-code.com</a> 了解原因和申诉方式</li></ul><h2 id="工具调用错误" tabindex="-1">工具调用错误 <a class="header-anchor" href="#工具调用错误" aria-label="Permalink to “工具调用错误”">​</a></h2><p>以下错误发生在 AI 执行工具调用过程中（如读取网页、处理图片），<strong>不影响对话本身继续使用</strong>，只是当前这一步操作没有成功。</p><p>如果看到的是认证或限流类错误（如 401、429），请参考前面的对应章节。</p><h3 id="请求被取消" tabindex="-1">请求被取消 <a class="header-anchor" href="#请求被取消" aria-label="Permalink to “请求被取消”">​</a></h3><p><strong>HTTP 499</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error sending &#39;CallDataSourceTool&#39; request: Post &quot;http://...&quot;: context canceled</span></span>
<span class="line"><span>canceled: context canceled</span></span></code></pre></div><p>客户端在收到结果之前主动中断了连接，通常是用户手动停止操作、网络中断或客户端超时触发。不是服务端错误。</p><p><strong>处理方式：</strong></p><ul><li>用户主动停止属正常行为，无需处理</li><li>频繁出现且非主动触发时，检查客户端超时配置是否过短</li></ul><h3 id="网页读取失败" tabindex="-1">网页读取失败 <a class="header-anchor" href="#网页读取失败" aria-label="Permalink to “网页读取失败”">​</a></h3><p><strong>HTTP 500</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>url2text:v2:fresh-request timeout</span></span>
<span class="line"><span>url-to-text request failed: 30001 invalid html</span></span>
<span class="line"><span>url-to-text request failed: 30041 check url failed, client error (4xx)</span></span>
<span class="line"><span>url-to-text request failed: 30043 check url failed, server error (5xx)</span></span>
<span class="line"><span>url-to-text request failed: 403 verify page</span></span>
<span class="line"><span>url-to-text request failed: 500 url is in blacklist</span></span>
<span class="line"><span>spider checkUrl failed: Post &quot;...&quot;: context deadline exceeded</span></span></code></pre></div><p>AI 尝试读取网页内容时失败。常见原因：目标页面响应超时、页面结构异常、需要登录验证、URL 在黑名单内，或目标服务器本身出错。</p><p><strong>处理方式：</strong></p><ul><li>超时或服务器错误：稍后重试</li><li>需要登录验证的页面（verify page）：无法通过工具读取，改为手动复制内容后粘贴给 AI</li><li>黑名单 URL：该地址被系统拦截，无法访问</li></ul><h3 id="图片审核失败" tabindex="-1">图片审核失败 <a class="header-anchor" href="#图片审核失败" aria-label="Permalink to “图片审核失败”">​</a></h3><p><strong>HTTP 500</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>image_url:moderation request error: 非法输入</span></span>
<span class="line"><span>image_url:Post &quot;https://api.msh.team/v1/moderations&quot;: context deadline exceeded</span></span></code></pre></div><p>AI 在处理图片时，图片内容审核服务返回错误或超时。</p><p><strong>处理方式：</strong></p><ul><li><code>非法输入</code>：图片内容触发了内容审核，请确认图片符合使用规范</li><li>超时：稍后重试，或检查网络连接是否正常</li></ul><h3 id="url-安全风险拦截" tabindex="-1">URL 安全风险拦截 <a class="header-anchor" href="#url-安全风险拦截" aria-label="Permalink to “URL 安全风险拦截”">​</a></h3><p><strong>HTTP 403</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(security_risk) We consider the current URL poses a security risk and are unable to provide fetch service at this time.</span></span></code></pre></div><p>工具调用中传入的 URL 被判定为安全风险，服务端拒绝抓取。</p><p><strong>处理方式：</strong></p><ul><li>内网地址（如 <code>192.168.x.x</code>、<code>10.x.x.x</code>）及已知风险域名会被拦截</li><li>需要登录才能访问的页面无法通过工具调用抓取</li></ul><h3 id="url-格式无效" tabindex="-1">URL 格式无效 <a class="header-anchor" href="#url-格式无效" aria-label="Permalink to “URL 格式无效”">​</a></h3><p><strong>HTTP 400</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(invalid_url) The provided URL is invalid: parse &quot;https://the repo for the contents of the path&quot;: invalid character &quot; &quot; in host name</span></span>
<span class="line"><span>(invalid_url) The provided URL is invalid: missing scheme</span></span></code></pre></div><p>模型将自然语言描述或格式有误的字符串作为 URL 传给工具，通常是描述性文字被当成地址传入，或缺少协议头。</p><p><strong>处理方式：</strong></p><ul><li>确认传入的是真实可访问的 URL，不是对 URL 的文字描述</li><li>协议头（<code>http://</code> 或 <code>https://</code>）不可省略</li></ul><h2 id="未覆盖的错误类型" tabindex="-1">未覆盖的错误类型 <a class="header-anchor" href="#未覆盖的错误类型" aria-label="Permalink to “未覆盖的错误类型”">​</a></h2><p>如以上条目未能覆盖你遇到的报错，请通过邮箱反馈 <a href="mailto:code@moonshot.ai" target="_blank" rel="noreferrer">code@moonshot.ai</a>，并附上完整的错误消息、Request ID 和请求时间。</p>`,196)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};